def content(number):
    row = ROWS[number-1]
    title, intro, result, question, answer = [pair(*row[i:i+2]) for i in range(0, 10, 2)]
    local = number in {1, 2, 7, 8, 16, 18, 20}
    execution = pair('LOKALNE WYKONANIE · dane kontrolne', 'LOCAL EXECUTION · controlled data') if local else pair('SYMULACJA AWS / INFRASTRUKTURY · bez połączenia z chmurą', 'SIMULATED AWS / INFRASTRUCTURE · no cloud connection')
    adaptation = pair('Aplikacja wykonuje Python lokalnie. AWS to adapter LocalCloud, polecenia pipeline są symulowane, alerty trafiają do pliku. Pokaz nie odczytuje kluczy AWS. Wyniki i pliki są osobne dla każdego uruchomienia.', 'The application executes Python locally. AWS uses LocalCloud, pipeline commands are simulated, alerts go to a file. The demonstration does not read AWS keys. Each run has separate results and files.')
    return dict(number=number, title=title, intro=intro, forecast=result, takeaway=result,
                watch=intro, question=question, answer=answer, execution=execution,
                pipeline=pair('Dane kontrolne → funkcja zadania → wynik → pliki dowodowe', 'Controlled inputs → task function → result → evidence files'),
                caveat=adaptation, adaptation=adaptation,
                extra_question=pair('Który fragment zmienia dane? Jak sprawdzisz wynik po błędzie?', 'Which part changes data? How would you check the result after failure?'),
                extra_answer=pair('Wskaż operację zapisu lub wywołanie klienta. Porównaj result.json, historię i pliki z przewidywanym wynikiem. Symulacja nie potwierdza uprawnień IAM ani działania prawdziwego AWS.', 'Locate the write or client operation. Compare result.json, history and files to the prediction. Simulation does not verify IAM permissions or real AWS behavior.'),
                presets=[dict(label='Dane kontrolne / Controlled inputs', value={})], terms=[])
